 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){

return float4(color.rgb*_Tint.rgb*_Brightness,color.a*_Tint.a*_Opacity);
}

// @whimtex-effect Learn/Core Light Rays
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param point _Origin = (0.17, 0.5)
// @param float _CoreSize = 0.023 [0.005 .. 0.08]
// @param float _RayLength = 0.20 [0.02 .. 0.4]
// @param float _RayWidth = 0.0015 [0.0003 .. 0.008]
// @param float _RayCount = 24 [4 .. 40]
// @param float _RayStrength = 0.9 [0 .. 2]
// @param float _Glow = 0.15 [0 .. 1]
// @param float _Seed = 71 [1 .. 5000]
// @param gradient _Light = #FF6B05 -> #FFFFF0
float CoreHash(float n) { return frac(sin(n*127.1+_Seed*31.7)*43758.5453); }
float4 ApplyFX(float2 uv,float4 color) {
 float2 p=LayerToLocal(uv)-_Origin;
 p.y*=0.5368421053;
 float core=2.5*exp(-dot(p/float2(_CoreSize,_CoreSize*.65),p/float2(_CoreSize,_CoreSize*.65))*2);
 float rays=0;
 [unroll] for(int k=0;k<40;k++){
   if(k>=(int)_RayCount) break;
   float h=CoreHash(k+2),h2=CoreHash(k+64),h3=CoreHash(k+171);
   float angle=lerp(-1.43,1.43,(k+.25+.5*h)/max(_RayCount,1));
   float2 dir=float2(cos(angle),sin(angle));
   float along=dot(p,dir);
   float across=dot(p,float2(-dir.y,dir.x));
   float len=_RayLength*(.5+.5*h2)*lerp(1,.45,abs(sin(angle)));
   float z=saturate(along/max(len,.001));
   float width=_RayWidth*(.55+.9*h3)*pow(1-z,1.25);
   float aa=max(fwidth(across)*.55,.00025);
   float shaft=exp(-pow(across/max(width,aa),2));
   float envelope=pow(1-z,1.25)*smoothstep(-aa,aa,along)*(1-smoothstep(.82,1,z));
   rays+=shaft*envelope*(.4+.8*h)*_RayStrength;
 }
 float halo=exp(-dot(p,p)/max(_CoreSize*_CoreSize*5,.00001))*_Glow;
 float energy=core+rays+halo;
 float4 tint=_Light_Sample(1-exp(-energy*1.25));
 return float4(tint.rgb,(1-exp(-energy*2))*tint.a*_Opacity);
}

// @whimtex-effect Distortion/Spherize
// @group(Spherize Mode; _Mode)
// @param hidden enum _Mode = 0 {Classic: 0, Sphere: 1} // Classic is the current unbounded radial distortion. Sphere wraps the image over a sphere and clips outside its circular edge.
// @param float _Strength = 0.5 [~-1 .. ~1]
// @param transform2D _Area
// @endgroup

float4 ApplyFX(float2 uv, float4 color)
{
    float2 p = (_Area_ToLocal(uv) - 0.5) * 2.0;
    float4 result = color;

    if (_Mode < 0.5)
    {
        if (_Strength != 0)
        {
            float exponent = exp2(_Strength);
            // The epsilon only protects the center; the radius is not limited to the frame.
            float scale = pow(max(dot(p, p), 1e-12), 0.5 * (exponent - 1.0));
            result = SampleInput(_Area_ToInput(0.5 + p * scale * 0.5));
        }
    }
    else
    {
        float radius = length(p);
        float clampedRadius = saturate(radius);
        // A sphere maps the disk to its angular surface coordinates. Positive values bulge;
        // negative values use the inverse mapping and pinch toward the center.
        float sphericalRadius = _Strength >= 0.0
            ? asin(clampedRadius) * 0.6366197723675814
            : sin(clampedRadius * 1.5707963267948966);
        float strength = abs(_Strength);
        float sampleRadius = lerp(radius, sphericalRadius, min(strength, 1.0));
        float excessStrength = max(strength - 1.0, 0.0);
        // Beyond one, continue strengthening smoothly without clamping the soft UI range.
        if (_Strength >= 0.0)
            sampleRadius *= exp2(-excessStrength * (1.0 - sampleRadius));
        else
            sampleRadius = 1.0 - (1.0 - sampleRadius) * exp2(-excessStrength * sampleRadius);
        float radialScale = sampleRadius / max(radius, 1e-6);
        result = SampleInput(_Area_ToInput(0.5 + p * radialScale * 0.5));

        // Keep a crisp circular silhouette with a sub-pixel antialiased edge.
        float edgeWidth = max(fwidth(radius), 1e-4);
        result.a *= 1.0 - smoothstep(1.0 - edgeWidth, 1.0 + edgeWidth, radius);
    }

    return result;
}

// @whimtex-effect Color/Levels
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1] // Blend between the original and corrected colors.
// @group
// @header(Input Levels)
// @param label(Input Black) float _InBlack = 0 [0 .. ~1] // Input black point. At or above white, the mapping becomes a hard threshold.
// @param label(Input White) float _InWhite = 1 [0 .. ~1] // Input white point.
// @param float _Gamma = 1 [0.1 .. ~5] // Midtone brightness.
// @param curve _Curve // Remap tones after input levels and Gamma, before output levels. Linear leaves the mapping unchanged.
// @header(Output Levels)
// @param label(Output Black) float _OutBlack = 0 [0 .. ~1] // Output black point, including originally black pixels.
// @param label(Output White) float _OutWhite = 1 [0 .. ~1] // Output white point; values below black invert the output.
// @param bool _PreserveColor = true // On adjusts luminance; off applies levels independently to RGB.
// @endgroup

float MapLevels(float value)
{
    float mapped;
    if (_InWhite <= _InBlack) mapped = step(_InBlack, value);
    else mapped = saturate((value - _InBlack) / (_InWhite - _InBlack));
    mapped = pow(mapped, 1.0 / max(_Gamma, 0.0001));
    mapped = _Curve_Sample(mapped);
    return lerp(_OutBlack, _OutWhite, mapped);
}

float4 ApplyFX(float2 uv, float4 color)
{
	float4 result = color;
    float3 rgb = max(color.rgb, 0.0);
    if (_PreserveColor > 0.5)
    {
        float luma = dot(rgb, float3(0.2126, 0.7152, 0.0722));
        float mapped = MapLevels(luma);
		result.rgb = luma > 0.000001 ? rgb * (mapped / max(luma, 0.000001)) : mapped.xxx;
	}
	else
	{
		result.rgb = float3(MapLevels(rgb.r), MapLevels(rgb.g), MapLevels(rgb.b));
	}
	return lerp(color, result, _Opacity);
}

// @whimtex-effect Color/Gradient Map
// @control(_Opacity)
// @group
// @formerlyserializedas(_Amount)
// @param hidden float _Opacity = 1 [0 .. 1] // Blend the mapped colors and gradient opacity with the original image.
// @param enum _SourceChannel = Luminance {Luminance: 0, R: 1, G: 2, B: 3, Alpha: 4} // Select the input used to look up the full gradient color. RGB uses sRGB values; alpha is read directly.
// @param gradient _Gradient // Colors from shadows to highlights; gradient alpha multiplies source alpha.
// @param curve _Mapping // Remap the selected input before sampling the gradient; the default is unchanged.
// @param bool _Reverse = false // Map highlights to the beginning of the gradient instead of shadows.
// @endgroup

#ifndef WHIMTEX_HDR_COLOR_INCLUDED
#define WHIMTEX_HDR_COLOR_INCLUDED
float3 SpriteEncode(float3 color)
{
    float3 value = abs(color);
    return sign(color) * lerp(value * 12.92, 1.055 * pow(value, 1.0 / 2.4) - .055, step(.0031308, value));
}
float3 SpriteDecode(float3 color)
{
    float3 value = abs(color);
    return sign(color) * lerp(value / 12.92, pow((value + .055) / 1.055, 2.4), step(.04045, value));
}
#endif


float4 ApplyFX(float2 uv, float4 color)
{
    float luminance = saturate(dot(max(color.rgb, 0.0), float3(0.2126, 0.7152, 0.0722)));
    float brightness = SpriteEncode(float3(luminance, luminance, luminance)).r;
    if (_SourceChannel > 3.5) brightness = saturate(color.a);
    else if (_SourceChannel > .5)
    {
        float channel = _SourceChannel < 1.5 ? color.r : _SourceChannel < 2.5 ? color.g : color.b;
        brightness = SpriteEncode(saturate(channel).xxx).r;
    }
    float t = _Reverse > 0.5 ? 1.0 - brightness : brightness;
    float4 mapped = _Gradient_Sample(_Mapping_Sample(t));
    float amount = saturate(_Opacity);
    return float4(lerp(color.rgb, mapped.rgb, amount), color.a * lerp(1.0, mapped.a, amount));
}

// @whimtex-effect Learn/Flash Spark Shower
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param point _Origin = (0.17, 0.5)
// @param float _Seed = 361 [1 .. ~5000]
// @param float _Count = 30 [1 .. 64]
// @param float _Size = 0.0026 [0.0005 .. 0.02]
// @param float _Distance = 0.41 [0 .. 1]
// @param float _Spread = 0.25 [0.01 .. 0.5]
// @param gradient _SparkGradient = #FFB026 -> #FFE2B2
float ShowerHash(float x){return frac(sin(x*127.1+_Seed*31.7)*43758.5453);}
float4 ApplyFX(float2 uv,float4 color) {
 float2 p=LayerToLocal(uv)-_Origin;
 float dots=0;
 [unroll] for(int k=0;k<64;k++) {
  if(k >= (int)_Count) break;
  float h=ShowerHash(k+1), h2=ShowerHash(k+83), h3=ShowerHash(k+174);
  float2 c=float2((.04+.37*pow(h,.8))*(_Distance/.41),(h2*2-1)*_Spread*(.35+.65*sqrt(h)));
  float2 d=p-c;
  float size=max(.65/_CanvasSize.x,_Size*(.4+1.5*h3));
  float core=exp(-dot(d/float2(size,size*1.5),d/float2(size,size*1.5))*2);
  float halo=exp(-dot(d,d)/(size*size*7))*.2;
  dots+=core*2.4+halo;
 }
 // Gradient coordinate: outer glow (0) to the center of a spark (1).
 float profile=saturate(dots/2.6);
 float4 spark=_SparkGradient_Sample(profile);
 float alpha=(1-exp(-dots*1.7))*_Opacity*spark.a;
 return float4(spark.rgb,alpha);
}

// @whimtex-effect Learn/Turbulent Flash Jet
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param point _Origin = (0.17, 0.5)
// @param float _Length = 0.78 [0.1 .. 1]
// @param float _Width = 0.16 [0.02 .. 0.4]
// @param float _Core = 1.6 [0 .. 4]
// @param float _Turbulence = 0.8 [0 .. 1]
// @param float _Filaments = 0.25 [0 .. 2]
// @param float _Seed = 123 [1 .. ~5000]
// @param float _Texture = 0.75 [0 .. 1]
// @param float _HeatExposure = 0.65 [0.1 .. 2]
// @param gradient _Heat = #FF3500 -> #FFFFFF
float FlashHash(float x) { return frac(sin(x*127.1+_Seed*31.7)*43758.5453); }
float FlashNoise(float2 p) {
 fnl_state s=fnlCreateState((int)_Seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float4 ApplyFX(float2 uv,float4 color) {
 float2 p=LayerToLocal(uv)-_Origin;
 float t=p.x/max(_Length,.001);
 float u=saturate(t);
 float n=FlashNoise(float2(t*11,p.y*38));
 float detail=FlashNoise(float2(t*27,p.y*125));
 float warp=(FlashNoise(float2(t*10,3.1))-.5)*.022*u;
 float y=p.y-warp;
 float width=max(.004,_Width*pow(sin(u*3.14159265),.78));
 float env=exp(-pow(abs(y)/width,2.2))*pow(1-u,2.5);
 float gas=env*pow(saturate(n*1.9-.4),1.45)*(.65+.5*detail)*lerp(1,1.45,_Turbulence);
 float tongues=0;
 // Forward tongues only; retain their original noise identities.
 [unroll] for(int branch=0;branch<3;branch++) {
   int j=branch==0?2:branch==1?5:6;
   float side=branch==0?.035:branch==1?-.045:0;
   float reach=branch==0?.86:branch==1?.83:.97;
   float z=saturate(t/reach);
   float center=side*pow(z,.75)+(FlashNoise(float2(z*9,j*4.3))-.5)*.012*z;
   float w=(j==6?.035:.024+.014*FlashHash(j+840))*pow(sin(z*3.14159265),.8);
   float n2=FlashNoise(float2(t*17,p.y*90+j*13));
   w *= lerp(.65+.65*n2,.28+1.4*n2,_Texture);
   float crossSection=exp(-pow(abs(p.y-center)/max(w,.001),1.7));
   tongues+=crossSection*pow(1-z,1.0)*(.65+.35*n2)*smoothstep(0,.09,t);
 }
 gas=gas*.55+tongues*.55;
 float coreWidth=(.024+.14*sqrt(u))*pow(1-u,1.9);
 coreWidth*=lerp(1,.7+.6*FlashNoise(float2(t*20,p.y*30)),_Texture*smoothstep(.02,.2,u));
 float core=exp(-pow(abs(y)/max(coreWidth,.001),1.7))*exp(-u*9.0)*_Core*2.8;
 core*=lerp(1,.68+detail*.72,_Turbulence*u);
 core*=lerp(1,.28+1.25*detail,_Texture*smoothstep(.08,.32,u));
 float threads=0;
 [unroll] for(int k=0;k<22;k++) {
   float h=FlashHash(k+1), h2=FlashHash(k+71);
   float side=(h*2-1);
   float lengthRay=.24+.7*pow(1-abs(side),1.4);
   float z=saturate(t/lengthRay);
   float center=side*_Width*1.3*pow(max(t,0),.7)+(FlashNoise(float2(t*8,k*3.7))-.5)*.012*z;
   float w=(.0013+.005*h2)*pow(max(1-z,.001),.7);
   w=max(w, .5/_CanvasSize.y);
   float filament=exp(-pow((p.y-center)/w,2))*pow(sin(z*3.14159265),.8);
   threads+=filament*(.16+.5*h2)*pow(1-z,.4);
 }
 float v=(core+gas*2.7*pow(1-u,1.1)+threads*_Filaments)*smoothstep(-.005,.015,t)*(1-smoothstep(.87,1,t));
 float streak=FlashNoise(float2(t*21,p.y*105));
 v*=lerp(1,.22+1.55*streak,_Texture*smoothstep(.16,.55,u));
 float heat=1-exp(-max(v,0)*_HeatExposure);
 float3 rgb=_Heat_Sample(heat).rgb;
 float alpha=saturate(1-exp(-v*3.2))*_Opacity;
 return float4(rgb,alpha);
}

