// @whimtex-effect Learn/Four Flame Petals
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param point _Origin = (0.17, 0.5)
// @param float _Size = 1 [0.2 .. 1.5]
// @param float _Width = 0.028 [0.002 .. 0.06]
// @param float _HeatStrength = 1 [0 .. 3]
// @param float _Turbulence = 0.7 [0 .. 1]
// @param float _Seed = 29 [1 .. ~5000]
// @param float _HeatExposure = 0.65 [0.1 .. 2]
// @param gradient _Heat = #FF3500 -> #FFFFFF
float PetalNoise(float2 p) {
 fnl_state s=fnlCreateState((int)_Seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float4 ApplyFX(float2 uv,float4 color) {
 float2 p=(LayerToLocal(uv)-_Origin)/max(_Size,.001);
 float energy=0;
 [unroll] for(int k=0;k<4;k++) {
   float2 ray=k==0?float2(-.127,.445):k==1?float2(.091,.318):k==2?float2(-.132,-.438):float2(.079,-.29);
   float len=length(ray);float2 dir=ray/len;
   float t=dot(p,dir)/len;
   float transverse=dot(p,float2(-dir.y,dir.x));
   float z=saturate(t);
   float bend=(PetalNoise(float2(z*6,k*7.3))-.5)*.013*z*_Turbulence;
   float w=max(.0005,_Width*pow(sin(z*3.14159265),1.25)*(1-z*.3));
   float body=exp(-pow(abs(transverse-bend)/w,1.7))*.825*pow(sin(z*3.14159265),.8)*.78;
   float hot=exp(-pow((transverse-bend)/(w*.48),2))*exp(-pow((z-.32)/.115,2))*3.2*_HeatStrength;
   float innerGlow=exp(-pow((transverse-bend)/(w*.75),2))*.10153155;
   energy=max(energy,(body+hot+innerGlow)*smoothstep(.035,.11,t)*(1-smoothstep(.86,1,t)));
 }
 float3 rgb=_Heat_Sample((1-exp(-max(energy,0)*_HeatExposure))).rgb;
 return float4(rgb,saturate(1-exp(-energy*3.2))*_Opacity);
}
